PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?gameLabel ?rootNodeLabel
WHERE {
  ?game a gt:Game ;
        rdfs:label ?gameLabel ;
        gt:hasRootNode ?rootNode .
  ?rootNode rdfs:label ?rootNodeLabel .
}

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?playerLabel ?comment
WHERE {
  ?player a gt:Player ;
          rdfs:label ?playerLabel .
  OPTIONAL { ?player rdfs:comment ?comment . }
}

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?nodeLabel ?playerLabel ?actionLabel
WHERE {
  ?node a gt:DecisionNode ;
        rdfs:label ?nodeLabel ;
        gt:belongsToPlayer ?player ;
        gt:hasAction ?action .
  ?player rdfs:label ?playerLabel .
  ?action gt:actionLabel ?actionLabel .
}
ORDER BY ?nodeLabel ?actionLabel

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?nodeLabel ?actionLabel ?probability
WHERE {
  ?node a gt:ChanceNode ;
        rdfs:label ?nodeLabel ;
        gt:hasAction ?action .
  ?action gt:actionLabel ?actionLabel ;
          gt:hasProbability ?probability .
}
ORDER BY ?nodeLabel DESC(?probability)

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?outcomeLabel ?comment
WHERE {
  ?outcome a gt:OutcomeNode ;
           rdfs:label ?outcomeLabel .
  OPTIONAL { ?outcome rdfs:comment ?comment . }
}
ORDER BY ?outcomeLabel

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?outcomeLabel ?playerLabel ?utility
WHERE {
  ?outcome a gt:OutcomeNode ;
           rdfs:label ?outcomeLabel ;
           gt:hasPayoff ?payoff .
  ?payoff gt:forPlayer ?player ;
          gt:utilityValue ?utility .
  ?player rdfs:label ?playerLabel .
}
ORDER BY ?outcomeLabel ?playerLabel

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?playerLabel ?outcomeLabel ?utility
WHERE {
  ?outcome a gt:OutcomeNode ;
           rdfs:label ?outcomeLabel ;
           gt:hasPayoff ?payoff .
  ?payoff gt:forPlayer ?player ;
          gt:utilityValue ?utility .
  ?player rdfs:label ?playerLabel .
}
ORDER BY ?playerLabel DESC(?utility)

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?playerLabel (MAX(?utility) AS ?bestUtility)
WHERE {
  ?payoff a gt:Payoff ;
          gt:forPlayer ?player ;
          gt:utilityValue ?utility .
  ?player rdfs:label ?playerLabel .
}
GROUP BY ?playerLabel
ORDER BY DESC(?bestUtility)

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?playerLabel (MIN(?utility) AS ?worstUtility)
WHERE {
  ?payoff a gt:Payoff ;
          gt:forPlayer ?player ;
          gt:utilityValue ?utility .
  ?player rdfs:label ?playerLabel .
}
GROUP BY ?playerLabel
ORDER BY ?worstUtility

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?actionLabel ?probability ?targetNodeLabel
WHERE {
  ?action a gt:Action ;
          gt:actionLabel ?actionLabel ;
          gt:hasProbability ?probability ;
          gt:leadsToNode ?targetNode .
  ?targetNode rdfs:label ?targetNodeLabel .
}
ORDER BY DESC(?probability)

PREFIX gt: <http://trustgraph.ai/schemas/gametheory#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?playerLabel (COUNT(DISTINCT ?node) AS ?decisionPoints)
WHERE {
  ?node a gt:DecisionNode ;
        gt:belongsToPlayer ?player .
  ?player rdfs:label ?playerLabel .
}
GROUP BY ?playerLabel
ORDER BY DESC(?decisionPoints)
